import{_ as n,o as t,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Anleitung zur Dokumentenversion und -wartung","description":"","frontmatter":{},"headers":[],"relativePath":"de/99-文档版本与维护说明.md","filePath":"de/99-文档版本与维护说明.md","lastUpdated":null}'),s={name:"de/99-文档版本与维护说明.md"};function a(u,e,l,o,d,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="anleitung-zur-dokumentenversion-und-wartung" tabindex="-1">Anleitung zur Dokumentenversion und -wartung <a class="header-anchor" href="#anleitung-zur-dokumentenversion-und-wartung" aria-label="Permalink to &quot;Anleitung zur Dokumentenversion und -wartung&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Element</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>99</td></tr><tr><td>Modul</td><td>Anhänge und Referenzmaterialien</td></tr><tr><td>Schlüsselwörter</td><td>Versionsverwaltung, Wartungsanleitung, Dokumentennormen, Update-Protokoll, Einstellungswartung</td></tr></tbody></table><h2 id="_1-uberblick-uber-das-dokumentensystem" tabindex="-1">1. Überblick über das Dokumentensystem <a class="header-anchor" href="#_1-uberblick-uber-das-dokumentensystem" aria-label="Permalink to &quot;1. Überblick über das Dokumentensystem&quot;">​</a></h2><p>Das Einstellungssystem der Anker-Symbiose-Zivilisation besteht aus 100 Markdown-Dokumenten, nummeriert von 00 bis 99, unterteilt in zehn Module, wobei jedes Modul 10 Dokumente enthält. Das Dokumentensystem übernimmt SPEC.md (Normen für die Dokumentenerstellung) als strenge Einschränkung, 00-Übersicht über das Hengyuanzhou-Universum als allgemeine Richtlinie, die Dokumente jedes Moduls werden aus verschiedenen Dimensionen detailliert erweitert, und schließlich führen die Anhangsdokumente 90-99 die Indizierung, Zusammenfassung und Organisation durch. Das gesamte Dokumentensystem bildet eine vollständige, logisch selbstkonsistente, hierarchisch klare und gegenseitig referenzierende Einstellungswissensdatenbank.</p><p>Das Design des Dokumentensystems folgt drei Prinzipien: &quot;modular, strukturiert, erweiterbar&quot;. Modular bedeutet, dass jedes Dokument sich auf ein bestimmtes Thema konzentriert und unabhängig vollständig ist; strukturiert bedeutet, dass alle Dokumente einheitliche Formatnormen befolgen, was das Lesen und Suchen erleichtert; erweiterbar bedeutet, dass das Dokumentensystem ausreichend Erweiterungsraum reserviert und die Einstellungen durch die Überarbeitung vorhandener Dokumente und das Hinzufügen neuer Inhalte kontinuierlich verbessert werden können.</p><h2 id="_2-regeln-fur-die-versionsnummerierung" tabindex="-1">2. Regeln für die Versionsnummerierung <a class="header-anchor" href="#_2-regeln-fur-die-versionsnummerierung" aria-label="Permalink to &quot;2. Regeln für die Versionsnummerierung&quot;">​</a></h2><p>Das Dokumentensystem übernimmt die dreistufige Versionsnummerierungsregel &quot;Hauptversionsnummer.Nebenversionsnummer.Revisionsnummer&quot;:</p><table tabindex="0"><thead><tr><th>Versionsstufe</th><th>Nummerierungsregel</th><th>Auslösebedingung</th><th>Beispiel</th></tr></thead><tbody><tr><td>Hauptversionsnummer</td><td>Erhöht sich ab 1</td><td>Wichtige strukturelle Anpassungen im Dokumentensystem, wie z. B. erneute Aufteilung von Modulen, Änderungen von Kerneinstellungen</td><td>v1.0 → v2.0</td></tr><tr><td>Nebenversionsnummer</td><td>Erhöht sich ab 0</td><td>Wesentliche Überarbeitung der Kerninhalte eines Dokuments oder Hinzufügung wichtiger Einstellungsinhalte</td><td>v1.0 → v1.1</td></tr><tr><td>Revisionsnummer</td><td>Erhöht sich ab 0</td><td>Textkorrekturen, Formatanpassungen, Terminologievereinheitlichung und andere nicht wesentliche Änderungen</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>Die aktuelle Gesamtversion des Dokumentensystems ist v1.0, also die erste vollständige Veröffentlichungsversion. Jedes Dokument zeichnet seine eigene Versionsnummer in seinem Dokumentinformationsblock auf, und die Gesamtversionsnummer des Dokumentensystems wird einheitlich in diesem Dokument aufgezeichnet.</p><h2 id="_3-ruckblick-auf-die-dokumentformatnormen" tabindex="-1">3. Rückblick auf die Dokumentformatnormen <a class="header-anchor" href="#_3-ruckblick-auf-die-dokumentformatnormen" aria-label="Permalink to &quot;3. Rückblick auf die Dokumentformatnormen&quot;">​</a></h2><p>Alle Dokumente müssen den folgenden einheitlichen Formatnormen folgen (detaillierte Normen siehe SPEC.md):</p><h3 id="_3-1-dateibenennung" tabindex="-1">3.1 Dateibenennung <a class="header-anchor" href="#_3-1-dateibenennung" aria-label="Permalink to &quot;3.1 Dateibenennung&quot;">​</a></h3><p>Das Format des Dateinamens lautet <code>XX-Dokumenttitel.md</code>, wobei XX eine zweistellige Zahlenummer von 00 bis 99 ist, der Titel auf Chinesisch ist, ohne Leerzeichen.</p><h3 id="_3-2-dokumentstruktur" tabindex="-1">3.2 Dokumentstruktur <a class="header-anchor" href="#_3-2-dokumentstruktur" aria-label="Permalink to &quot;3.2 Dokumentstruktur&quot;">​</a></h3><p>Jedes Dokument muss die folgenden Strukturelemente enthalten:</p><ol><li><strong>Titel der ersten Ebene</strong>: Dokumenttitel (stimmt mit dem Dateinamen überein)</li><li><strong>Dokumentinformationsblock</strong>: Tabelle mit Nummer, Modul, Schlüsselwörtern (3-5)</li><li><strong>Haupttext</strong>: Mindestens 3 Kapitel mit Titeln der zweiten Ebene, Verwendung strukturierter Elemente wie Listen, Tabellen</li><li><strong>Schlusswort</strong>: Kurzer zusammenfassender Absatz</li><li><strong>Verwandte Dokumente</strong>: Auflistung von 2-3 Nummern und Namen verwandter Dokumente</li></ol><h3 id="_3-3-anforderungen-an-die-wortzahl" tabindex="-1">3.3 Anforderungen an die Wortzahl <a class="header-anchor" href="#_3-3-anforderungen-an-die-wortzahl" aria-label="Permalink to &quot;3.3 Anforderungen an die Wortzahl&quot;">​</a></h3><p>Der Haupttext jedes Dokuments sollte nicht weniger als 800 Zeichen betragen (ohne Titel und Metadaten).</p><h3 id="_3-4-schreibstil" tabindex="-1">3.4 Schreibstil <a class="header-anchor" href="#_3-4-schreibstil" aria-label="Permalink to &quot;3.4 Schreibstil&quot;">​</a></h3><ul><li>Ernsthafter, systematischer Einstellungsdokumentenstil, ähnlich einer Enzyklopädie/Einstellungssammlung</li><li>Verwendung einheitlicher Terminologie wie &quot;Hengyuanzhou&quot;, &quot;Anker&quot;, &quot;Symbiose&quot;</li><li>Ergänzte neue Einstellungen müssen logisch selbstkonsistent mit bestehenden Einstellungen sein und dem Prinzip &quot;auf der Realität basierend, Gesetze aktualisieren&quot; entsprechen</li></ul><h2 id="_4-wartungsorganisation-und-verantwortlichkeiten" tabindex="-1">4. Wartungsorganisation und Verantwortlichkeiten <a class="header-anchor" href="#_4-wartungsorganisation-und-verantwortlichkeiten" aria-label="Permalink to &quot;4. Wartungsorganisation und Verantwortlichkeiten&quot;">​</a></h2><h3 id="_4-1-ausschuss-fur-einstellungswartung" tabindex="-1">4.1 Ausschuss für Einstellungswartung <a class="header-anchor" href="#_4-1-ausschuss-fur-einstellungswartung" aria-label="Permalink to &quot;4.1 Ausschuss für Einstellungswartung&quot;">​</a></h3><p>Der Ausschuss für Einstellungswartung ist das höchste Wartungsorgan des Dokumentensystems, bestehend aus erfahrenen Einstellungserstellern, Experten für logische Überprüfung und Benutzervertretern. Seine Kernverantwortlichkeiten umfassen:</p><ul><li>Genehmigung der Gesamtarchitektur und wichtigen Überarbeitungspläne des Dokumentensystems</li><li>Prüfung wichtiger Einstellungsänderungen, Sicherstellung der Konsistenz mit den Kerneinstellungen</li><li>Entscheidung über Einstellungskonflikte, Bereitstellung maßgeblicher Erklärungen</li><li>Regelmäßige Organisation umfassender Selbstprüfungen der Einstellungskonsistenz</li><li>Veröffentlichung von Gesamtversionsupdates des Dokumentensystems</li></ul><h3 id="_4-2-modulwart" tabindex="-1">4.2 Modulwart <a class="header-anchor" href="#_4-2-modulwart" aria-label="Permalink to &quot;4.2 Modulwart&quot;">​</a></h3><p>Jedes Modul benennt einen Modulwart, der für die tägliche Wartung der 10 Dokumente dieses Moduls verantwortlich ist. Seine Verantwortlichkeiten umfassen:</p><ul><li>Nachverfolgung der Einstellungskonsistenz der Dokumente innerhalb des Moduls</li><li>Prüfung von Überarbeitungsanträgen für Dokumente innerhalb des Moduls</li><li>Koordinierung der Querverweise zwischen Dokumenten innerhalb des Moduls</li><li>Sammlung von Benutzerfeedback und Vorschlägen zum Modulinhalt</li><li>Regelmäßige Berichterstattung über den Wartungsstatus des Moduls an den Ausschuss für Einstellungswartung</li></ul><h3 id="_4-3-dokumentenersteller" tabindex="-1">4.3 Dokumentenersteller <a class="header-anchor" href="#_4-3-dokumentenersteller" aria-label="Permalink to &quot;4.3 Dokumentenersteller&quot;">​</a></h3><p>Jeder qualifizierte Ersteller kann an der Erstellung und Überarbeitung von Dokumenten teilnehmen. Die Verantwortlichkeiten des Erstellers umfassen:</p><ul><li>Erstellung oder Überarbeitung von Dokumenten gemäß den Formatnormen</li><li>Sicherstellung, dass der erstellte Inhalt die Prüfung der Tabelle zur Selbstprüfung von Einstellungskonflikten besteht</li><li>Beifügung detaillierter Überarbeitungsanweisungen bei der Einreichung der Überarbeitung</li><li>Mitarbeit bei den Prüfungsarbeiten der Wartenden und des Ausschusses</li></ul><h2 id="_5-uberarbeitungsprozess" tabindex="-1">5. Überarbeitungsprozess <a class="header-anchor" href="#_5-uberarbeitungsprozess" aria-label="Permalink to &quot;5. Überarbeitungsprozess&quot;">​</a></h2><h3 id="_5-1-regularer-uberarbeitungsprozess" tabindex="-1">5.1 Regulärer Überarbeitungsprozess <a class="header-anchor" href="#_5-1-regularer-uberarbeitungsprozess" aria-label="Permalink to &quot;5.1 Regulärer Überarbeitungsprozess&quot;">​</a></h3><ol><li><strong>Antrag einreichen</strong>: Der Ersteller reicht einen Überarbeitungsantrag beim Modulwart ein, einschließlich der überarbeiteten Dokumentennummer, der Beschreibung des Überarbeitungsinhalts und des Überarbeitungsgrunds.</li><li><strong>Modulprüfung</strong>: Der Modulwart prüft den Überarbeitungsinhalt, mit Schwerpunkt auf der Prüfung der Formatnormen und der internen Konsistenz des Moduls. Nach bestandener Prüfung wird er an den Ausschuss für Einstellungswartung weitergeleitet.</li><li><strong>Ausschussgenehmigung</strong>: Der Ausschuss für Einstellungswartung führt die endgültige Genehmigung des Überarbeitungsinhalts durch, mit Schwerpunkt auf der Prüfung der modulübergreifenden Konsistenz und der Konsistenz der Kerneinstellungen.</li><li><strong>Überarbeitung durchführen</strong>: Nach bestandener Genehmigung führt der Modulwart oder der ursprüngliche Ersteller die Dokumentenüberarbeitung durch.</li><li><strong>Version aktualisieren</strong>: Nach Abschluss der Überarbeitung wird die Dokumentversionsnummer aktualisiert und im Update-Protokoll dieses Dokuments aufgezeichnet.</li><li><strong>Zugehörige Synchronisation</strong>: Wenn der Überarbeitungsinhalt andere Dokumente betrifft, müssen die zugehörigen Dokumente synchron überarbeitet werden.</li></ol><h3 id="_5-2-notfall-uberarbeitungsprozess" tabindex="-1">5.2 Notfall-Überarbeitungsprozess <a class="header-anchor" href="#_5-2-notfall-uberarbeitungsprozess" aria-label="Permalink to &quot;5.2 Notfall-Überarbeitungsprozess&quot;">​</a></h3><p>Für Notfälle, in denen schwerwiegende Einstellungskonflikte oder -fehler entdeckt werden, kann der Notfall-Überarbeitungsprozess gestartet werden:</p><ol><li><strong>Notfallbericht</strong>: Der Entdecker meldet das Problem unverzüglich dem Ausschuss für Einstellungswartung.</li><li><strong>Schnellgenehmigung</strong>: Der Ausschuss schließt die Notfallgenehmigung innerhalb von 24 Stunden ab und stellt einen Überarbeitungsplan bereit.</li><li><strong>Überarbeitung durchführen</strong>: Es wird eine bestimmte Person ernannt, um die Überarbeitung unverzüglich durchzuführen.</li><li><strong>Nachträgliche Aufzeichnung</strong>: Nach Abschluss der Überarbeitung werden der Überarbeitungsantrag und die Prüfungsaufzeichnungen nachträglich ergänzt.</li></ol><h3 id="_5-3-regelmaßige-umfassende-uberarbeitung" tabindex="-1">5.3 Regelmäßige umfassende Überarbeitung <a class="header-anchor" href="#_5-3-regelmaßige-umfassende-uberarbeitung" aria-label="Permalink to &quot;5.3 Regelmäßige umfassende Überarbeitung&quot;">​</a></h3><p>Der Ausschuss für Einstellungswartung organisiert einmal jährlich eine umfassende Überarbeitung des Dokumentensystems, einschließlich:</p><ul><li>Umfassende Selbstprüfung der Einstellungskonsistenz</li><li>Zentrale Verarbeitung von Benutzerfeedback</li><li>Vereinheitlichung und Aktualisierung des Terminologiesystems</li><li>Synchrones Aktualisieren von Indexdokumenten</li><li>Einheitliche Prüfung und Korrektur des Dokumentenformats</li></ul><h2 id="_6-update-protokoll" tabindex="-1">6. Update-Protokoll <a class="header-anchor" href="#_6-update-protokoll" aria-label="Permalink to &quot;6. Update-Protokoll&quot;">​</a></h2><h3 id="v1-0-erste-vollstandige-veroffentlichung" tabindex="-1">v1.0 (Erste vollständige Veröffentlichung) <a class="header-anchor" href="#v1-0-erste-vollstandige-veroffentlichung" aria-label="Permalink to &quot;v1.0 (Erste vollständige Veröffentlichung)&quot;">​</a></h3><ul><li>Abschluss der Erstellung und Veröffentlichung aller 100 Dokumente</li><li>Einrichtung der vollständigen Architektur und Formatnormen des Dokumentensystems</li><li>Abschluss der Inhaltsabdeckung der zehn Module</li><li>Einrichtung des Anhangs-Indexsystems (Terminologiewörterbuch, Systemindex, Rechtsindex, Chronik, Verzeichnis aller Völker, Personen und Organisationen, FAQ, Selbstprüfungstabelle, Erweiterungsvorschläge, Versionsanleitung)</li></ul><h3 id="bereich-fur-die-aufzeichnung-nachfolgender-versionsupdates" tabindex="-1">Bereich für die Aufzeichnung nachfolgender Versionsupdates <a class="header-anchor" href="#bereich-fur-die-aufzeichnung-nachfolgender-versionsupdates" aria-label="Permalink to &quot;Bereich für die Aufzeichnung nachfolgender Versionsupdates&quot;">​</a></h3><p>(Die Update-Inhalte nachfolgender Versionen werden hier ergänzt aufgezeichnet, einschließlich Versionsnummer, Veröffentlichungsdatum, Zusammenfassung der Hauptupdate-Inhalte)</p><h2 id="_7-normen-fur-dokumentenzitate-und-querverweise" tabindex="-1">7. Normen für Dokumentenzitate und Querverweise <a class="header-anchor" href="#_7-normen-fur-dokumentenzitate-und-querverweise" aria-label="Permalink to &quot;7. Normen für Dokumentenzitate und Querverweise&quot;">​</a></h2><h3 id="_7-1-interne-zitate" tabindex="-1">7.1 Interne Zitate <a class="header-anchor" href="#_7-1-interne-zitate" aria-label="Permalink to &quot;7.1 Interne Zitate&quot;">​</a></h3><p>Querverweise zwischen Dokumenten verwenden das Format &quot;Dokumentennummer-Dokumenttitel&quot;, z. B. &quot;siehe Dokument 84 &#39;Allgemeines Programm des Archäologieprotokolls&#39;&quot;. Beim Zitieren muss sichergestellt werden, dass das zitierte Dokument tatsächlich existiert und Nummer sowie Titel korrekt sind.</p><h3 id="_7-2-terminologie-zitate" tabindex="-1">7.2 Terminologie-Zitate <a class="header-anchor" href="#_7-2-terminologie-zitate" aria-label="Permalink to &quot;7.2 Terminologie-Zitate&quot;">​</a></h3><p>Bei der ersten Verwendung eines Kernbegriffs kann darauf hingewiesen werden, dass der entsprechende Eintrag in Dokument 90 &quot;Terminologiewörterbuch&quot; nachgeschlagen werden sollte. Bei der späteren Verwendung desselben Begriffs muss nicht wiederholt darauf hingewiesen werden.</p><h3 id="_7-3-externe-zitate" tabindex="-1">7.3 Externe Zitate <a class="header-anchor" href="#_7-3-externe-zitate" aria-label="Permalink to &quot;7.3 Externe Zitate&quot;">​</a></h3><p>Wenn auf reale Materialien oder fiktive Werke außerhalb des Einstellungssystems verwiesen werden muss, muss die Quelle angegeben und klar erläutert werden, dass diese Zitierung ein Referenzmaterial nach dem Prinzip &quot;auf der Realität basierend&quot; ist und nicht bedeutet, dass das Einstellungssystem deren Inhalt vollständig übernimmt.</p><h2 id="_8-qualitatssicherungsmechanismus" tabindex="-1">8. Qualitätssicherungsmechanismus <a class="header-anchor" href="#_8-qualitatssicherungsmechanismus" aria-label="Permalink to &quot;8. Qualitätssicherungsmechanismus&quot;">​</a></h2><h3 id="_8-1-selbstprufung-von-einstellungskonflikten" tabindex="-1">8.1 Selbstprüfung von Einstellungskonflikten <a class="header-anchor" href="#_8-1-selbstprufung-von-einstellungskonflikten" aria-label="Permalink to &quot;8.1 Selbstprüfung von Einstellungskonflikten&quot;">​</a></h3><p>Alle neu erstellten und überarbeiteten Dokumente müssen alle Prüfpunkte von Dokument 97 &quot;Tabelle zur Selbstprüfung von Einstellungskonflikten&quot; bestehen, einschließlich mehr als 40 Prüfungen in drei Kategorien: Konsistenz der Kerneinstellungen, logische Konsistenz zwischen Modulen und Dokumentformatnormen.</p><h3 id="_8-2-gegenseitige-prufung" tabindex="-1">8.2 Gegenseitige Prüfung <a class="header-anchor" href="#_8-2-gegenseitige-prufung" aria-label="Permalink to &quot;8.2 Gegenseitige Prüfung&quot;">​</a></h3><p>Jedes Dokument muss vor der offiziellen Veröffentlichung die gegenseitige Prüfung durch mindestens einen anderen Ersteller bestehen, mit Schwerpunkt auf der Prüfung der logischen Konsistenz zwischen Modulen und der Vereinheitlichung der Terminologie.</p><h3 id="_8-3-benutzerfeedback-mechanismus" tabindex="-1">8.3 Benutzerfeedback-Mechanismus <a class="header-anchor" href="#_8-3-benutzerfeedback-mechanismus" aria-label="Permalink to &quot;8.3 Benutzerfeedback-Mechanismus&quot;">​</a></h3><p>Das Dokumentensystem richtet einen Benutzerfeedback-Kanal ein, über den Benutzer auf folgende Weise Feedback einreichen können:</p><ul><li>Meldung von Einstellungskonflikten und logischen Fehlern</li><li>Einreichung von Problemen bei der Terminologievereinheitlichung</li><li>Vorschläge zur Ergänzung oder Überarbeitung bestimmter Inhalte</li><li>Hinweis auf Format- und Textfehler</li></ul><p>Das gesamte Feedback wird vom Modulwart klassifiziert verarbeitet, und wichtiges Feedback wird zur Beratung an den Ausschuss für Einstellungswartung weitergeleitet.</p><h3 id="_8-4-vierteljahrlicher-konsistenzbericht" tabindex="-1">8.4 Vierteljährlicher Konsistenzbericht <a class="header-anchor" href="#_8-4-vierteljahrlicher-konsistenzbericht" aria-label="Permalink to &quot;8.4 Vierteljährlicher Konsistenzbericht&quot;">​</a></h3><p>Der Ausschuss für Einstellungswartung veröffentlicht jedes Quartal einen &quot;Einstellungskonsistenzbericht&quot;, dessen Inhalt umfasst:</p><ul><li>In diesem Quartal entdeckte Einstellungskonflikte und Verarbeitungsstatus</li><li>Statistiken zur Dokumentenüberarbeitung in diesem Quartal</li><li>Fortschritt bei der Terminologievereinheitlichung</li><li>Verarbeitungsstatus des Benutzerfeedbacks</li><li>Wartungsplan für das nächste Quartal</li></ul><h2 id="_9-speicherung-und-verteilung-von-dokumenten" tabindex="-1">9. Speicherung und Verteilung von Dokumenten <a class="header-anchor" href="#_9-speicherung-und-verteilung-von-dokumenten" aria-label="Permalink to &quot;9. Speicherung und Verteilung von Dokumenten&quot;">​</a></h2><h3 id="_9-1-speicherformat" tabindex="-1">9.1 Speicherformat <a class="header-anchor" href="#_9-1-speicherformat" aria-label="Permalink to &quot;9.1 Speicherformat&quot;">​</a></h3><p>Alle Dokumente werden im Markdown-Format (.md) gespeichert, um die plattformübergreifende Lesbarkeit und die Bequemlichkeit der Versionsverwaltung zu gewährleisten. Die Dokumente verwenden die UTF-8-Kodierung und unterstützen Chinesisch und Sonderzeichen.</p><h3 id="_9-2-verzeichnisstruktur" tabindex="-1">9.2 Verzeichnisstruktur <a class="header-anchor" href="#_9-2-verzeichnisstruktur" aria-label="Permalink to &quot;9.2 Verzeichnisstruktur&quot;">​</a></h3><p>Die Dokumente werden einheitlich im Verzeichnis <code>anchor-docs/</code> gespeichert, der Dateiname hat das Format <code>XX-Dokumenttitel.md</code>. SPEC.md wird als Normdatei ebenfalls im selben Verzeichnis gespeichert.</p><h3 id="_9-3-versionsverwaltung" tabindex="-1">9.3 Versionsverwaltung <a class="header-anchor" href="#_9-3-versionsverwaltung" aria-label="Permalink to &quot;9.3 Versionsverwaltung&quot;">​</a></h3><p>Es wird empfohlen, Versionsverwaltungssysteme wie Git zur Verwaltung der Dokumentversionen zu verwenden, wobei bei jeder Einreichung einer Überarbeitung eine detaillierte Commit-Nachricht beigefügt wird, die den Überarbeitungsinhalt und -grund aufzeichnet.</p><h3 id="_9-4-verteilungsmethoden" tabindex="-1">9.4 Verteilungsmethoden <a class="header-anchor" href="#_9-4-verteilungsmethoden" aria-label="Permalink to &quot;9.4 Verteilungsmethoden&quot;">​</a></h3><p>Das Dokumentensystem kann auf folgende Weise verteilt werden:</p><ul><li>Als ZIP-komprimiertes Paket zum Download verpacken</li><li>Als statische Website für das Online-Browsen bereitstellen</li><li>In das PDF- oder EPUB-Format zum Lesen konvertieren</li><li>In ein Wissensdatenbanksystem zur strukturierten Verwaltung importieren</li></ul><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Die Anleitung zur Dokumentenversion und -wartung ist die &quot;Verwaltungsverfassung&quot; des Einstellungssystems der Anker-Symbiose-Zivilisation. Sie legt die Versionsregeln, die Wartungsorganisation, den Überarbeitungsprozess, den Qualitätssicherungsmechanismus sowie die Speicherungs- und Verteilungsmethoden des Dokumentensystems fest und stellt sicher, dass dieses riesige, aus 100 Dokumenten bestehende Einstellungssystem im Prozess des kontinuierlichen Wachstums stets Ordnung und Konsistenz bewahren kann. Ein gutes Einstellungssystem braucht nicht nur hervorragende Inhalte, sondern auch einen perfekten Wartungsmechanismus, um seine langfristige gesunde Entwicklung zu gewährleisten. Dieses Dokument ist genau der Kernträger dieses Mechanismus.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>97-Tabelle zur Selbstprüfung von Einstellungskonflikten</li><li>90-Terminologiewörterbuch</li><li>00-Übersicht über das Hengyuanzhou-Universum</li></ul>',77)])])}const c=n(s,[["render",a]]);export{m as __pageData,c as default};
